package in.aicon.pocket;
import android.content.*;import java.lang.reflect.Constructor;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class AccountDirectoryTest {
 Context context;AccountDirectory directory;
 // Test-only constructor access avoids network and never adds a production identity bypass.
 VerifiedDriveAccess identity(String subject,String email)throws Exception{Constructor<VerifiedDriveAccess> constructor=VerifiedDriveAccess.class.getDeclaredConstructor(String.class,String.class,String.class);constructor.setAccessible(true);return constructor.newInstance(subject,email,"fake-token-for-unit-tests-only");}
 @Before public void setup(){context=RuntimeEnvironment.getApplication();context.getSharedPreferences("hisab-account-directory",0).edit().clear().commit();directory=new AccountDirectory(context);}
 @Test public void verificationDoesNotSelectOrAdoptAndSelectionSurvivesReopen()throws Exception{assertNull(directory.selectedSubject());VerifiedDriveAccess a=identity("1234567890","a@example.invalid");directory.record(a);assertNull(directory.selectedSubject());directory.selectKnown(a.subject);assertEquals(a.subject,new AccountDirectory(context).selectedSubject());directory.record(identity("9876543210","b@example.invalid"));assertEquals(a.subject,directory.selectedSubject());directory.selectLocal();assertNull(directory.selectedSubject());assertEquals(2,directory.entries().size());String stored=context.getSharedPreferences("hisab-account-directory",0).getString("accounts","");assertFalse(stored.contains("fake-token"));a.clear();try{directory.record(a);fail();}catch(DriveAppData.NeedsSignIn expected){}}
 @Test public void unknownAndCorruptSelectionCannotOpenLedger()throws Exception{try{directory.selectKnown("1234567890");fail();}catch(IllegalArgumentException expected){}try{LedgerSession.remembered(context,directory,"1234567890");fail();}catch(IllegalArgumentException expected){}context.getSharedPreferences("hisab-account-directory",0).edit().putString("selected","1234567890").commit();try{directory.selectedSubject();fail();}catch(IllegalStateException expected){}}
 @Test public void forgetReturnsToLocalWithoutClaimingCloudDeletion()throws Exception{VerifiedDriveAccess identity=identity("1234567890","a@example.invalid");directory.record(identity);directory.selectKnown(identity.subject);LedgerSession cache=LedgerSession.remembered(context,directory,identity.subject);assertTrue(cache.accountLedger());cache.close();directory.forget(identity.subject);assertNull(directory.selectedSubject());assertTrue(directory.entries().isEmpty());assertTrue(context.getDatabasePath(AccountScope.databaseFor(identity.subject)).exists());}
}
